@font-face {
  font-family: Inter;
  src: url("data:font/woff2;base64,") format("woff2");
  font-weight: 400 700;
  font-display: swap;
}

:root {
  color-scheme: dark;
  --bg: #000;
  --composer: #111;
  --surface: #161616;
  --raised: #1e1e1e;
  --hover: #2d2d2d;
  --line: #555;
  --quiet-line: #333;
  --text: #f5f5f5;
  --muted: #a1a1a1;
  --accent: #d6d6d6;
  --error: #d6d6d6;
  --edge: clamp(16px, 6vw, 48px);
  --pill: 999px;
  --panel-radius: 24px;
  --composer-width: 504px;
  --chat-width: 680px;
  --ease: cubic-bezier(.2, .7, .2, 1);
  --dur-fast: 120ms;
  --dur-base: 240ms;
  --dur-slow: 600ms;
  --dur-dock: 360ms;
  --fast: var(--dur-fast);
  --base: var(--dur-base);
  --reveal-distance: 16px;
  --control-radius: 8px;
  --menu-radius: 14px;
  --border: rgb(255 255 255 / .10);
  --border-strong: rgb(255 255 255 / .20);
  --glass-face: linear-gradient(90deg, #464646, #757575, #494949);
  --glass-halo: conic-gradient(transparent 80deg, #505050, #b5b5b5, #666 245deg, transparent 280deg);
  --glass-inset: inset 0 0 5px rgb(255 255 255 / .48), inset 0 31px 26px #000;
  --glass-radius: 12px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 400 15px/1.6 Inter, system-ui, sans-serif;
}

button,
textarea,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

a {
  color: var(--accent);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.dots {
  position: fixed;
  inset: 0;
  pointer-events: none;

  transition: opacity var(--base) var(--ease);
}

body:has(.app.is-chat) .dots {
  opacity: .65;
}

.dots {
  overflow: hidden;
}

.dots::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: center / max(1440px, 100vw) max(900px, 100dvh) no-repeat url("data:image/svg+xml;base64,");
  animation: dot-drift 34s ease-in-out infinite alternate;
}

body.pause-background .dots::before {
  animation-play-state: paused;
}

@keyframes dot-drift {
  from { transform: translate3d(-12px, -8px, 0); }
  to { transform: translate3d(12px, 8px, 0); }
}

.model-chevron {
  width: 6px;
  height: 6px;
  margin: -3px 2px 0 4px;
  border: solid var(--muted);
  border-width: 0 1px 1px 0;
  transform: rotate(45deg);
}

.model-mark[data-brand="openai"] {
  background-image: url("./openai.png");
  border-radius: 4px;
}

.model-mark[data-brand="qwen"] {
  background-image: url("data:image/svg+xml;base64,");
  filter: none;
}

.model-options {
  display: grid;
  gap: 8px;
  margin-top: 20px;
}

.model-option {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 12px;
  align-items: center;
  min-height: 56px;
  padding: 8px 12px;
  border-radius: var(--control-radius);
  border: 1px solid var(--border);
  background: var(--composer);
  text-align: left;
  transition: background-color var(--fast) var(--ease), border-color var(--fast) var(--ease);
}

.model-option:hover { background: var(--raised); }
.model-option[aria-pressed="true"] { border-color: var(--accent); }
.model-option .model-mark { grid-row: span 2; }
.model-option small { color: var(--muted); }
.connection-status { text-align: center; color: var(--muted); font-size: 13px; }

#signInAction {
  margin-top: clamp(16px, 4dvh, 32px);
}

