.sign-in-button,
#signInSubmit {
  position: relative;
  isolation: isolate;
  min-height: 44px;
  padding-inline: 22px;
  border: 0;
  border-radius: var(--glass-radius);
  background: var(--glass-face);
  box-shadow: var(--glass-inset), 0 5px 10px rgb(0 0 0 / .65);
  color: var(--text);
  text-shadow: 0 1px 2px #000;
  font-weight: 600;
  transition: box-shadow var(--base) var(--ease);
}

:is(.sign-in-button, #signInSubmit)::before {
  content: "";
  position: absolute;
  inset: 1px;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  background: var(--glass-halo);
  filter: blur(10px);
  opacity: 0;
  transition: opacity var(--base) var(--ease), filter var(--base) var(--ease);
}

:is(.sign-in-button, #signInSubmit):is(:hover, :focus-visible):not(:disabled)::before {
  opacity: .58;
}

:is(.sign-in-button, #signInSubmit):active:not(:disabled) {
  box-shadow: var(--glass-inset);
}

:is(.sign-in-button, #signInSubmit):active:not(:disabled)::before {
  filter: blur(4px);
}

dialog .motion-option {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  margin: 8px 0 0;
  color: var(--muted);
}

dialog .motion-option input {
  width: 16px;
  min-height: 0;
  height: 16px;
  accent-color: var(--accent);
}

.app {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100vh;
  height: 100dvh;
  padding: max(20px, env(safe-area-inset-top)) max(var(--edge), env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(var(--edge), env(safe-area-inset-left));
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
}

.wordmark {
  margin: 0;
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -.02em;
}

.wordmark strong {
  font-weight: 700;
}

.brand {
  text-align: center;
  margin-bottom: 12px;
}

.brand .wordmark {
  font-size: clamp(32px, 4vw, 36px);
  line-height: 1.22;
}

.slogan {
  color: var(--muted);
  margin: 4px 0 0;
  font-size: 13px;
  line-height: 18px;
}

.dock {
  width: min(100%, var(--composer-width));
  margin: 0 auto;
}

.opening .brand .wordmark {
  animation: fade-in var(--dur-slow) var(--ease) both;
}

.opening .slogan {
  animation: fade-in var(--dur-slow) var(--ease) var(--fast) both;
}

.opening .composer,
.opening .model {
  animation: appear var(--dur-slow) var(--ease) var(--base) both;
}

.opening .model {
  animation-delay: calc(var(--base) + var(--fast));
}

.opening:focus-within :is(.wordmark, .slogan, .composer, .model) {
  animation: none;
}

.app:not(.is-chat) .dock {
  grid-row: 1 / -1;
  align-self: center;
}

.app.is-chat .dock {
  grid-row: 3;
  padding-top: 12px;
}

.composer {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 0 3px 0 23px;
  border: 1px solid var(--line);
  border-radius: 32px;
  background: var(--composer);
  transition: border-color var(--fast) var(--ease);
}

.composer:focus-within {
  border-color: var(--accent);
}

.composer textarea {
  flex: 1;
  min-width: 0;
  height: 24px;
  max-height: min(144px, 25dvh);
  resize: none;
  display: block;
  border: 0;
  padding: 0;
  background: transparent;
  font-size: 16px;
  line-height: 24px;
  outline: 0;
}

.composer textarea::placeholder {
  color: var(--muted);
  opacity: 1;
}

.icon-button {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: var(--pill);
  color: var(--muted);
  background: transparent;
  transition: background-color var(--fast) var(--ease),
    color var(--fast) var(--ease), opacity var(--fast) var(--ease),
    transform var(--fast) var(--ease);
}

.icon-button:hover {
  background: var(--raised);
  color: var(--text);
}

.icon-button:disabled {
  cursor: default;
  opacity: .4;
}

.icon-button:active:not(:disabled) {
  transform: translateY(1px);
}

.icon-button svg {
  width: 20px;
  height: 20px;
}

.send,
.stop {
  position: relative;
  isolation: isolate;
  width: 44px;
  height: 44px;
  margin-block: -1px;
  background: transparent;
  color: var(--text);
}

.send:hover:not(:disabled),
.stop:hover {
  background: transparent;
}

.send::before,
.stop::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 5px;
  border-radius: var(--pill);
  background: var(--raised);
  transition: background-color var(--fast) var(--ease);
}

.send:hover:not(:disabled)::before,
.stop:hover::before {
  background: var(--hover);
}

.send .send-mark {
  width: 18px;
  height: 18px;
  background: center / contain no-repeat url("data:image/svg+xml;base64,");
}

.send:not([hidden]) .send-mark,
.stop:not([hidden]) svg {
  animation: fade-in var(--fast) var(--ease) both;
}

.model {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 8px auto 0;
  min-height: 44px;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--pill);
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  line-height: 20px;
  transition: background-color var(--fast) var(--ease);
}

.model:hover {
  background: var(--composer);
}

.provider {
  color: var(--muted);
  font-size: 12px;
}

/* Qwen team mark from https://github.com/QwenLM */
.model-mark {
  filter: grayscale(1);
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  background: center / contain no-repeat url("data:image/png;base64,");
}

.thread {
  min-height: 0;
  min-width: 0;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--quiet-line) transparent;
  overscroll-behavior: contain;
}

.messages {
  width: min(100%, var(--chat-width));
  margin: 0 auto;
  padding: clamp(24px, 7vh, 64px) 0 12px;
  display: flex;
  flex-direction: column;
  gap: clamp(24px, 4vh, 40px);
}

.message {
  min-width: 0;
  animation: appear var(--base) var(--ease) both;
}

.is-chat .messages > .message:first-child {
  animation-delay: var(--fast);
}

.is-chat .messages > .agent:nth-child(2) {
  animation-delay: calc(var(--fast) + 60ms);
}

.user {
  align-self: flex-end;
  max-width: 87%;
  padding: 12px 20px;
  border-radius: var(--panel-radius);
  background: var(--surface);
}

.agent {
  align-self: stretch;
}

.agent-name {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0 0 12px;
  font-size: 13px;
  font-weight: 500;
}

.message-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.status {
  color: var(--muted);
  font-size: 13px;
  margin: 0;
}

.status.is-error {
  color: var(--error);
}

.actions {
  display: flex;
  gap: 4px;
  margin: 4px 0 0 -12px;
}

.actions:not([hidden]) {
  animation: fade-in var(--fast) var(--ease) both;
}

.status.is-waiting::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-inline-end: 8px;
  vertical-align: 2px;
  border-radius: var(--pill);
  background: currentColor;
  animation: waiting 1.2s var(--ease) infinite alternate;
}

@keyframes waiting {
  from {
    opacity: .35;
  }

  to {
    opacity: 1;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes appear {
  from {
    opacity: 0;
    transform: translateY(var(--reveal-distance));
  }
}

.enter {
  animation: appear var(--base) var(--ease) both;
}

dialog {
  width: min(calc(100% - 32px), 416px);
  max-height: calc(100dvh - 32px);
  padding: 24px;
  border: 1px solid var(--border-strong);
  border-radius: var(--menu-radius);
  background: var(--surface);
  color: var(--text);
  opacity: 0;
  transform: translateY(var(--reveal-distance));
  transition: opacity var(--base) var(--ease), transform var(--base) var(--ease);
  transition: opacity var(--base) var(--ease), transform var(--base) var(--ease),
    display var(--base) allow-discrete, overlay var(--base) allow-discrete;
}

dialog[open] {
  opacity: 1;
  transform: translateY(0);
}

dialog::backdrop {
  background-color: transparent;
  transition: background-color var(--base) var(--ease);
  transition: background-color var(--base) var(--ease),
    display var(--base) allow-discrete, overlay var(--base) allow-discrete;
}

dialog[open]::backdrop {
  background-color: rgb(0 0 0 / .8);
}

@starting-style {
  dialog[open] {
    opacity: 0;
    transform: translateY(var(--reveal-distance));
  }

  dialog[open]::backdrop {
    background-color: transparent;
  }
}

.dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dialog-header .icon-button {
  margin: -8px -8px -8px 0;
}

dialog h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
}

dialog p {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 13px;
}

dialog a {
  color: var(--text);
  text-underline-offset: 3px;
}

dialog label {
  display: block;
  margin: 20px 0 8px;
  font-size: 13px;
  font-weight: 500;
}

dialog input {
  width: 100%;
  min-height: 48px;
  background: var(--composer);
  border: 1px solid var(--line);
  border-radius: var(--control-radius);
  padding: 8px 12px;
  font-size: 16px;
  transition: border-color var(--fast) var(--ease);
}

dialog input[aria-invalid="true"] {
  border-color: var(--error);
}

dialog .key-error {
  color: var(--error);
}

.dialog-actions {
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.dialog-actions button {
  min-height: 48px;
  padding: 8px 20px;
  border: 1px solid var(--border);
  border-radius: var(--pill);
  background: transparent;
  transition: background-color var(--fast) var(--ease), filter var(--fast) var(--ease),
    transform var(--fast) var(--ease);
}

.dialog-actions button:hover {
  background: var(--raised);
}

.dialog-actions button:active {
  transform: translateY(1px);
}

@media (max-width: 600px) {
  .dots {
    mask-image: radial-gradient(ellipse closest-side, #000 45%, rgb(0 0 0 / .35) 100%);
  }

  .brand {
    margin-bottom: 20px;
  }
}

@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }

  dialog::backdrop {
    transition: none;
  }

  dialog,
  dialog[open],
  .icon-button:active:not(:disabled),
  .dialog-actions button:active {
    transform: none;
  }
}
